// Writes supabase/setup.sql: every migration plus the seed in one file, for a
// project you can only reach through the dashboard SQL editor. Records each
// migration in schema_migrations so `npm run db` skips them later.
import { readdirSync, readFileSync, writeFileSync } from "node:fs";

const dir = new URL("../supabase/", import.meta.url);
const files = readdirSync(new URL("migrations/", dir)).filter((f) => f.endsWith(".sql")).sort();
const parts = [
  "-- Generated by scripts/bundle.mjs. Paste into the Supabase SQL editor and run once.",
  "create table if not exists public.schema_migrations (name text primary key, applied_at timestamptz not null default now());",
  "alter table public.schema_migrations enable row level security;",
  ...files.flatMap((f) => [
    `\n-- ===== ${f} =====`,
    readFileSync(new URL(`migrations/${f}`, dir), "utf8"),
    `insert into public.schema_migrations (name) values ('${f}') on conflict do nothing;`,
  ]),
  "\n-- ===== seed.sql =====",
  readFileSync(new URL("seed.sql", dir), "utf8"),
];
writeFileSync(new URL("setup.sql", dir), parts.join("\n"));
console.log(`supabase/setup.sql: ${files.length} migrations + seed`);
